<?php
use App\Application\Penalizaciones\GestionarPenalizaciones;
use App\Application\Penalizaciones\ConsultarPenalizaciones;
use App\Application\Operacion\ReglasOperativas;
use Illuminate\Support\Facades\Gate;
use Illuminate\Validation\ValidationException;
use Livewire\Component;
use Livewire\WithPagination;
use Livewire\Attributes\Locked;
use Mary\Traits\Toast;
new class extends Component {
 use WithPagination,Toast;
 public string $state=''; public string $producer=''; public string $reason='';
 public array $ruleForm=['activo'=>false,'tarifa_primera'=>'','tarifa_grave'=>'','alcance_tarifa'=>'','unidad_falta'=>'','ventana_dias'=>null,'motivo'=>''];
 public array $decision=['decision'=>'','decision_perdida'=>'','decision_expulsion'=>'','motivo'=>''];
 public array $assistanceForm=['estado'=>'programada','responsable_id'=>'','fecha_at'=>'','observaciones'=>'','motivo'=>''];
 #[Locked] public ?string $selected=null; #[Locked] public ?string $assistanceUuid=null;
 public function boot(): void { Gate::authorize('administrar-penalizaciones'); }
 public function mount(): void { $r=app(ReglasOperativas::class)->current('penalizaciones'); $this->ruleForm=array_intersect_key($r['valores'],$this->ruleForm)+$this->ruleForm; }
 public function updatedState(): void { Gate::authorize('administrar-penalizaciones'); $this->resetPage(); }
 public function show(string $uuid): void { Gate::authorize('administrar-penalizaciones'); app(ConsultarPenalizaciones::class)->find(auth()->id(),$uuid); $this->selected=$uuid; $this->decision=['decision'=>'','decision_perdida'=>'','decision_expulsion'=>'','motivo'=>'']; $this->resetValidation(); }
 public function showAssistance(string $uuid): void { Gate::authorize('administrar-penalizaciones'); $r=app(ConsultarPenalizaciones::class)->assistance(auth()->id(),$uuid); $this->assistanceUuid=$uuid; $this->assistanceForm=['estado'=>$r->estado==='pendiente'?'programada':$r->estado,'responsable_id'=>$r->responsable_id??'','fecha_at'=>$r->fecha_at?->format('Y-m-d\TH:i')??'','observaciones'=>$r->observaciones??'','motivo'=>'']; $this->resetValidation(); }
 public function saveRules(): void { Gate::authorize('administrar-penalizaciones'); $this->perform(function(): void { $data=$this->ruleForm; if($data['ventana_dias']==='') { $data['ventana_dias']=null; } app(GestionarPenalizaciones::class)->configure(auth()->id(),$data); $this->success('Reglas y tarifas aprobadas guardadas.'); }); }
 public function recalculate(): void { Gate::authorize('administrar-penalizaciones'); $this->perform(function(): void { $this->validate(['producer'=>'required|integer'],['required'=>'Selecciona un productor.','integer'=>'Productor inválido.']); app(GestionarPenalizaciones::class)->recalculate(auth()->id(),(int)$this->producer,$this->reason); $this->success('Recálculo controlado completado. Revisa las propuestas.'); }); }
 public function decide(): void { Gate::authorize('administrar-penalizaciones'); $this->perform(function(): void { app(GestionarPenalizaciones::class)->decide(auth()->id(),$this->selected,$this->decision); $this->success('Decisión auditada. No se ha expulsado automáticamente al productor.'); }); }
 public function annul(): void { Gate::authorize('administrar-penalizaciones'); $this->perform(function(): void { app(GestionarPenalizaciones::class)->annul(auth()->id(),$this->selected,$this->decision['motivo']); $this->success('Sanción anulada con auditoría.'); }); }
 public function saveAssistance(): void { Gate::authorize('administrar-penalizaciones'); $this->perform(function(): void { app(GestionarPenalizaciones::class)->assistance(auth()->id(),$this->assistanceUuid,$this->assistanceForm); $this->success('Asistencia actualizada.'); }); }
 private function perform(Closure $op): void { $this->resetValidation(); try { $op(); } catch(ValidationException $e) { foreach($e->errors() as $key=>$messages) { $this->addError($key,$messages[0]); } } catch(\Illuminate\Auth\Access\AuthorizationException $e) { throw $e; } catch(Throwable $e) { report($e); $this->addError('operacion','No se pudo completar la operación. Puedes reintentar.'); } }
 public function with(): array { $q=app(ConsultarPenalizaciones::class); return $q->options(auth()->id())+['records'=>$q->listing(auth()->id(),$this->state),'assistances'=>$q->assistances(auth()->id()),'detail'=>$this->selected?$q->find(auth()->id(),$this->selected):null,'audit'=>$this->selected?$q->audit(auth()->id(),$this->selected):[],'assistanceAudit'=>$this->assistanceUuid?$q->audit(auth()->id(),$this->assistanceUuid):[],'rule'=>app(ReglasOperativas::class)->current('penalizaciones')]; }
}; ?>
