s>@endforeach</x-card>@endif
 <x-card title="Asistencias técnicas por acidez" shadow><p>La acidez fuera del criterio vigente genera asistencia; no genera multa automática.</p><div class="overflow-x-auto"><table class="table"><thead><tr><th>Productor</th><th>Estado</th><th>Fecha</th><th>Fuente</th><th></th></tr></thead><tbody>@forelse($assistances as $r)<tr wire:key="asistencia-{{ $r->id }}"><td>{{ $r->productor->codigo }}</td><td>{{ $r->estado }}</td><td>{{ $r->fecha_at?->format('d/m/Y H:i') }}</td><td>{{ $r->requiere_revision?'Requiere revisión':($r->fuente_vigente?'Vigente':'Sin vigencia') }}</td><td><x-button label="Gestionar" wire:click="showAssistance('{{ $r->uuid }}')" class="btn-sm" /></td></tr>@empty<tr><td colspan="5">No hay asistencias detectadas.</td></tr>@endforelse</tbody></table></div>{{ $assistances->links() }}
 @if($assistanceUuid)<x-form wire:submit="saveAssistance"><x-select label="Estado" wire:model="assistanceForm.estado" :options="[['id'=>'programada','name'=>'Programada'],['id'=>'realizada','name'=>'Realizada'],['id'=>'cancelada','name'=>'Cancelada']]" /><x-select label="Responsable" wire:model="assistanceForm.responsable_id" :options="$usuarios" placeholder="Seleccionar" /><x-input label="Fecha y hora" type="datetime-local" wire:model="assistanceForm.fecha_at" /><x-textarea label="Observaciones" wire:model="assistanceForm.observaciones" /><x-textarea label="Motivo del cambio" wire:model="assistanceForm.motivo" /><x-slot:actions><x-button label="Guardar asistencia" type="submit" spinner="saveAssistance" /></x-slot:actions></x-form>@foreach($assistanceAudit as $item)<p wire:key="assistance-audit-{{ $item['id'] }}">{{ $item['accion'] }} · {{ $item['usuario']['name'] }} · {{ $item['created_at'] }} · {{ $item['motivo'] }}</p>@endforeach @endif</x-card>
